parameters.outputSchema:
{
  "type": "object",
  "required": [
    "action",
    "strategy",
    "entry_stage",
    "reasoning"
  ],
  "properties": {
    "action": {
      "enum": [
        "continue",
        "stop"
      ]
    },
    "strategy": {
      "type": "string",
      "description": "Free-form instruction the prompt rewriter will follow. Be specific about WHAT to change in the prompt and WHY. Empty string when action='stop'."
    },
    "entry_stage": {
      "enum": [
        "smoke",
        "quick",
        "full"
      ],
      "description": "Where to start the candidate's evaluation. 'smoke' = 10 rows (cheap probe); 'quick' = 100 stratified rows (refinement); 'full' = whole dataset (real candidate). Gates auto-promote smoke -> quick -> full if criteria met. Use 'smoke' on iter 0 and for any risky/exploratory edit."
    },
    "reasoning": {
      "type": "string",
      "description": "One sentence on why this action / strategy / stage."
    },
    "target_confusion_pair": {
      "type": "string",
      "description": "If strategy targets a specific gt->pred pair, name it (e.g. 'AccountCl->OutOfScop'). Empty string when none."
    }
  }
}

